  ('d4880ce5-ceba-4a47-ab83-04652cc1bd50', 'P1', 'State-mandated Requirement for Property and Casualty, see Claim Payment Remarks Code for specific explanation. To be used for Property and Casualty only.', true, '2013-11-01'::timestamp, NULL, NULL, 'This code replaces deactivated code 162', now(), now()),
  ('169bdce1-6f3a-4506-a9a9-fd63569b9919', 'P2', 'Not a work related injury/illness and thus not the liability of the workers'' compensation carrier Usage: If adjustment is at the Claim Level, the payer must send and the provider should refer to the 835 Insurance Policy Number Segment (Loop 2100 Other Claim Related Information REF qualifier ''IG'') for the jurisdictional regulation. If adjustment is at the Line Level, the payer must send and the provider should refer to the 835 Healthcare Policy Identification Segment (loop 2110 Service Payment information REF). To be used for Workers'' Compensation only.', true, '2013-11-01'::timestamp, '2017-07-01'::timestamp, NULL, 'This code replaces deactivated code 191', now(), now()),
  ('9802491e-0de4-4f7d-8863-89fa81c9276e', 'P3', 'Workers'' Compensation case settled. Patient is responsible for amount of this claim/service through WC ''Medicare set aside arrangement'' or other agreement. To be used for Workers'' Compensation only. (Use only with Group Code PR)', true, '2013-11-01'::timestamp, NULL, NULL, 'This code replaces deactivated code 201', now(), now()),
  ('0870a719-9773-4d26-b986-28236bdd780e', 'P4', 'Workers'' Compensation claim adjudicated as non-compensable. This Payer not liable for claim or service/treatment. Usage: If adjustment is at the Claim Level, the payer must send and the provider should refer to the 835 Insurance Policy Number Segment (Loop 2100 Other Claim Related Information REF qualifier ''IG'') for the jurisdictional regulation. If adjustment is at the Line Level, the payer must send and the provider should refer to the 835 Healthcare Policy Identification Segment (loop 2110 Service Payment information REF). To be used for Workers'' Compensation only', true, '2013-11-01'::timestamp, '2017-07-01'::timestamp, NULL, 'This code replaces deactivated code 214', now(), now()),
  ('69ead14c-0092-4295-b039-fc36edd3472a', 'P5', 'Based on payer reasonable and customary fees. No maximum allowable defined by legislated fee arrangement. To be used for Property and Casualty only.', true, '2013-11-01'::timestamp, NULL, NULL, 'This code replaces deactivated code 217', now(), now()),
  ('a77961fb-4deb-4ad3-b4bb-628655a9b24d', 'P6', 'Based on entitlement to benefits. Usage: If adjustment is at the Claim Level, the payer must send and the provider should refer to the 835 Insurance Policy Number Segment (Loop 2100 Other Claim Related Information REF qualifier ''IG'') for the jurisdictional regulation. If adjustment is at the Line Level, the payer must send and the provider should refer to the 835 Healthcare Policy Identification Segment (loop 2110 Service Payment information REF). To be used for Property and Casualty only.', true, '2013-11-01'::timestamp, '2017-07-01'::timestamp, NULL, 'This code replaces deactivated code 218', now(), now()),
  ('127619bb-f5dc-4798-838d-71def88cdfc5', 'P7', 'The applicable fee schedule/fee database does not contain the billed code. Please resubmit a bill with the appropriate fee schedule/fee database code(s) that best describe the service(s) provided and supporting documentation if required. To be used for Property and Casualty only.', true, '2013-11-01'::timestamp, NULL, NULL, 'This code replaces deactivated code 220', now(), now()),
  ('35b8f21a-53d7-47e2-a1b6-77f6697efd29', 'P8', 'Claim is under investigation. Usage: If adjustment is at the Claim Level, the payer must send and the provider should refer to the 835 Insurance Policy Number Segment (Loop 2100 Other Claim Related Information REF qualifier ''IG'') for the jurisdictional regulation. If adjustment is at the Line Level, the payer must send and the provider should refer to the 835 Healthcare Policy Identification Segment (loop 2110 Service Payment information REF). To be used for Property and Casualty only.', true, '2013-11-01'::timestamp, '2017-07-01'::timestamp, NULL, 'This code replaces deactivated code 221', now(), now()),
  ('4d9667bd-f24a-43d3-bddb-067072224b84', 'P9', 'No available or correlating CPT/HCPCS code to describe this service. To be used for Property and Casualty only.', true, '2013-11-01'::timestamp, NULL, NULL, 'This code replaces deactivated code 230', now(), now()),
