  ('3b37b100-63ae-4170-a049-2bdfbef80e18', 'M2', 'Not paid separately when the patient is an inpatient.', true, '1997-01-01'::timestamp, NULL, NULL, NULL, now(), now()),
  ('b269b11d-b4ea-4e10-8090-d9c8074526b6', 'M3', 'Equipment is the same or similar to equipment already being used.', true, '1997-01-01'::timestamp, NULL, NULL, NULL, now(), now()),
  ('14f8d2b6-9344-4ecb-98e0-ff551092b6ba', 'M4', 'Alert: This is the last monthly installment payment for this durable medical equipment.', true, '1997-01-01'::timestamp, '2007-04-01'::timestamp, NULL, '(Modified 4/1/07)', now(), now()),
  ('7c73a405-921f-4212-af7c-f3e8780e4d7f', 'M5', 'Monthly rental payments can continue until the earlier of the 15th month from the first rental month, or the month when the equipment is no longer needed.', true, '1997-01-01'::timestamp, NULL, NULL, NULL, now(), now()),
  ('dfe2ba1b-c6b6-4d95-ae7e-1b16366d2950', 'M6', 'Alert: You must furnish and service this item for any period of medical need for the remainder of the reasonable useful lifetime of the equipment.', true, '1997-01-01'::timestamp, '2009-03-01'::timestamp, NULL, '(Modified 4/1/07, 3/1/2009)', now(), now()),
  ('5651a9ab-0657-4501-80e9-f7a0adccdf04', 'M7', 'No rental payments after the item is purchased, returned or after the total of issued rental payments equals the purchase price.', true, '1997-01-01'::timestamp, '2016-11-01'::timestamp, NULL, '(Modified 11/1/2016)', now(), now()),
  ('d961dc7b-98f4-4938-b16e-a5335877d0e7', 'M8', 'We do not accept blood gas tests results when the test was conducted by a medical supplier or taken while the patient is on oxygen.', true, '1997-01-01'::timestamp, NULL, NULL, NULL, now(), now()),
  ('04239703-8c03-4c75-b628-b7c8ffa46c4a', 'M9', 'Alert: This is the tenth rental month. You must offer the patient the choice of changing the rental to a purchase agreement.', true, '1997-01-01'::timestamp, '2007-04-01'::timestamp, NULL, '(Modified 4/1/07)', now(), now()),
  ('d3f8e474-532a-47f1-a2df-d3b8607be1f7', 'M10', 'Equipment purchases are limited to the first or the tenth month of medical necessity.', true, '1997-01-01'::timestamp, NULL, NULL, NULL, now(), now()),
  ('f669ed94-8e9f-4a54-9e52-6d80dd4f1855', 'M11', 'DME, orthotics and prosthetics must be billed to the DME carrier who services the patient''s zip code.', true, '1997-01-01'::timestamp, NULL, NULL, NULL, now(), now()),
  ('768e7780-f0b8-45aa-8ab1-00c9873c4080', 'M12', 'Diagnostic tests performed by a physician must indicate whether purchased services are included on the claim.', true, '1997-01-01'::timestamp, NULL, NULL, NULL, now(), now()),
  ('e837b7b4-9d44-42fe-91af-83d87cc57184', 'M13', 'Only one initial visit is covered per specialty per medical group.', true, '1997-01-01'::timestamp, '2007-06-30'::timestamp, NULL, '(Modified 6/30/03)', now(), now()),
  ('d6d4695f-5279-4bf5-87c3-bc0c08204ea2', 'M14', 'No separate payment for an injection administered during an office visit, and no payment for a full office visit if the patient only received an injection.', true, '1997-01-01'::timestamp, NULL, NULL, NULL, now(), now()),
  ('4ff77739-365f-4e5a-a390-d3a2af28fd76', 'M15', 'Separately billed services/tests have been bundled as they are considered components of the same procedure. Separate payment is not allowed.', true, '1997-01-01'::timestamp, NULL, NULL, NULL, now(), now()),
  ('3e4a8b34-938f-4c64-90e9-b5dd0147608d', 'M16', 'Alert: Please see our web site, mailings, or bulletins for more details concerning this policy/procedure/decision.', true, '1997-01-01'::timestamp, '2007-04-01'::timestamp, NULL, '(Reactivated 4/1/04, Modified 11/18/05, 4/1/07)', now(), now()),
  ('db576553-058d-4b94-96d8-9b63c7c50538', 'M17', 'Alert: Payment approved as you did not know, and could not reasonably have been expected to know, that this would not normally have been covered for this patient. In the future, you will be liable for charges for the same service(s) under the same or similar conditions.', true, '1997-01-01'::timestamp, '2007-04-01'::timestamp, NULL, '(Modified 4/1/07)', now(), now()),
  ('2f1b631b-e906-4bca-a217-123312a0ddfa', 'M18', 'Certain services may be approved for home use. Neither a hospital nor a Skilled Nursing Facility (SNF) is considered to be a patient''s home.', true, '1997-01-01'::timestamp, '2003-06-30'::timestamp, NULL, '(Modified 6/30/03)', now(), now()),
  ('89d4e91d-97ba-4a46-bbe9-d237a6843395', 'M19', 'Missing oxygen certification/re-certification.', true, '1997-01-01'::timestamp, '2003-02-28'::timestamp, NULL, '(Modified 2/28/03) Related to N234', now(), now()),
  ('cda567f0-5deb-4763-b0b7-4e26555cc05f', 'M20', 'Missing/incomplete/invalid HCPCS.', true, '1997-01-01'::timestamp, '2003-02-28'::timestamp, NULL, '(Modified 2/28/03)', now(), now()),
  ('98959076-6552-4d0e-b9d9-9a96675f5fbe', 'M21', 'Missing/incomplete/invalid place of residence for this service/item provided in a home.', true, '1997-01-01'::timestamp, '2003-02-28'::timestamp, NULL, '(Modified 2/28/03)', now(), now()),
  ('032162f7-439f-43a9-8cb1-e4f7443557b6', 'M22', 'Missing/incomplete/invalid number of miles traveled.', true, '1997-01-01'::timestamp, '2003-02-28'::timestamp, NULL, '(Modified 2/28/03)', now(), now()),
  ('21a764a6-8174-49ff-ab9d-3c20d7b49441', 'M23', 'Missing invoice.', true, '1997-01-01'::timestamp, '2005-08-01'::timestamp, NULL, '(Modified 8/1/05)', now(), now()),
  ('9081de93-32d9-4f22-824e-a40807a81bdd', 'M24', 'Missing/incomplete/invalid number of doses per vial.', true, '1997-01-01'::timestamp, '2003-02-28'::timestamp, NULL, '(Modified 2/28/03)', now(), now()),
  ('b2ad6592-0b59-45c1-822e-36598780e9a8', 'M25', 'The information furnished does not substantiate the need for this level of service. If you believe the service should have been fully covered as billed, or if you did not know and could not reasonably have been expected to know that we would not pay for this level of service, or if you notified the patient in writing in advance that we would not pay for this level of service and he/she agreed in writing to pay, ask us to review your claim within 120 days of the date of this notice. If you do not request an appeal, we will, upon application from the patient, reimburse him/her for the amount you have collected from him/her in excess of any deductible and coinsurance amounts. We will recover the reimbursement from you as an overpayment.', true, '1997-01-01'::timestamp, '2010-11-01'::timestamp, NULL, '(Modified 10/1/02, 6/30/03, 8/1/05, 11/5/07, 11/1/10)', now(), now()),
  ('ce6decf7-62b4-4376-a2a3-c4acccb44a25', 'M26', 'The information furnished does not substantiate the need for this level of service. If you have collected any amount from the patient for this level of service/any amount that exceeds the limiting charge for the less extensive service, the law requires you to refund that amount to the patient within 30 days of receiving this notice. The requirements for refund are in 1824(I) of the Social Security Act and 42CFR411.408. The section specifies that physicians who knowingly and willfully fail to make appropriate refunds may be subject to civil monetary penalties and/or exclusion from the program. If you have any questions about this notice, please contact this office.', true, '1997-01-01'::timestamp, '2007-11-05'::timestamp, NULL, '(Modified 10/1/02, 6/30/03, 8/1/05, 11/5/07. Also refer to N356)', now(), now()),
  ('670f59e9-3ef8-4a34-95fe-61c911a97f01', 'M27', 'Alert: The patient has been relieved of liability of payment of these items and services under the limitation of liability provision of the law. The provider is ultimately liable for the patient''s waived charges, including any charges for coinsurance, since the items or services were not reasonable and necessary or constituted custodial care, and you knew or could reasonably have been expected to know, that they were not covered. You may appeal this determination. You may ask for an appeal regarding both the coverage determination and the issue of whether you exercised due care. The appeal request must be filed within 120 days of the date you receive this notice. You must make the request through this office.', true, '1997-01-01'::timestamp, '2007-08-01'::timestamp, NULL, '(Modified 10/1/02, 8/1/05, 4/1/07, 8/1/07)', now(), now()),
  ('c10ddde7-f844-43cd-b0ff-7555e9c845ce', 'M28', 'This does not qualify for payment under Part B when Part A coverage is exhausted or not otherwise available.', true, '1997-01-01'::timestamp, NULL, NULL, NULL, now(), now()),
