  ('45576e69-9970-423c-948e-e4725cc486c9', 'M144', 'Pre-/post-operative care payment is included in the allowance for the surgery/procedure.', true, '1997-01-01'::timestamp, NULL, NULL, NULL, now(), now()),
  ('556e4cea-c138-4fdd-8e2d-8571812850ff', 'MA01', 'Alert: If you do not agree with what we approved for these services, you may appeal our decision. To make sure that we are fair to you, we require another individual that did not process your initial claim to conduct the appeal. However, in order to be eligible for an appeal, you must write to us within 120 days of the date you received this notice, unless you have a good reason for being late.', true, '1997-01-01'::timestamp, '2007-04-01'::timestamp, NULL, '(Modified 10/31/02, 6/30/03, 8/1/05, 4/1/07)', now(), now()),
  ('740e3e8d-db8b-4270-a00e-28873e088949', 'MA02', 'Alert: If you do not agree with this determination, you have the right to appeal. You must file a written request for an appeal within 180 days of the date you receive this notice.', true, '1997-01-01'::timestamp, '2007-04-01'::timestamp, NULL, '(Modified 10/31/02, 6/30/03, 8/1/05, 12/29/05, 8/1/06, 4/1/07)', now(), now()),
  ('74448ab4-5f09-4f4a-befd-54d3397dddf3', 'MA03', 'If you do not agree with the approved amounts and $100 or more is in dispute (less deductible and coinsurance), you may ask for a hearing within six months of the date of this notice. To meet the $100, you may combine amounts on other claims that have been denied, including reopened appeals if you received a revised decision. You must appeal each claim on time.', false, '1997-01-01'::timestamp, '2005-11-18'::timestamp, '2006-10-01'::timestamp, 'Consider using MA02 (Modified 10/31/02, 6/30/03, 8/1/05, 11/18/05)', now(), now()),
  ('b3ca1d5c-6149-4600-b57e-a10e7135e85f', 'MA04', 'Secondary payment cannot be considered without the identity of or payment information from the primary payer. The information was either not reported or was illegible.', true, '1997-01-01'::timestamp, NULL, NULL, NULL, now(), now()),
  ('9ec535dd-79dd-41a3-8891-afc4a9361e21', 'MA05', 'Incorrect admission date patient status or type of bill entry on claim.', false, '1997-01-01'::timestamp, NULL, '2003-10-16'::timestamp, 'Consider using MA30, MA40 or MA43', now(), now()),
  ('0092a839-30d0-45e9-aa05-7fd0216fab52', 'MA06', 'Missing/incomplete/invalid beginning and/or ending date(s).', false, '1997-01-01'::timestamp, NULL, '2004-08-01'::timestamp, 'Consider using MA31', now(), now()),
  ('a857229b-539a-49f1-b900-41bae24ecf9f', 'MA07', 'Alert: The claim information has also been forwarded to Medicaid for review.', true, '1997-01-01'::timestamp, '2007-04-01'::timestamp, NULL, '(Modified 4/1/07)', now(), now()),
  ('89bb81b0-035d-4d29-8f2c-5737d14b94ad', 'MA08', 'Alert: Claim information was not forwarded because the supplemental coverage is not with a Medigap plan, or you do not participate in Medicare.', true, '1997-01-01'::timestamp, '2007-04-01'::timestamp, NULL, '(Modified 4/1/07)', now(), now()),
  ('29531751-6a2b-42e2-9d6e-cfc009bcf76b', 'MA09', 'Alert: Claim submitted as unassigned but processed as assigned in accordance with our current assignment/participation agreement.', true, '1997-01-01'::timestamp, '2015-11-01'::timestamp, NULL, '(Modified 11/1/2014, 11/1/2015)', now(), now()),
  ('44fabfb0-9a51-4a2b-be0c-ea90ad862597', 'MA10', 'Alert: The patient''s payment was in excess of the amount owed. You must refund the overpayment to the patient.', true, '1997-01-01'::timestamp, '2007-04-01'::timestamp, NULL, '(Modified 4/1/07)', now(), now()),
  ('abd5ed20-54b3-4160-aa77-1cb9e5d8d2c6', 'MA11', 'Payment is being issued on a conditional basis. If no-fault insurance, liability insurance, Workers'' Compensation, Department of Veterans Affairs, or a group health plan for employees and dependents also covers this claim, a refund may be due us. Please contact us if the patient is covered by any of these sources.', false, '1997-01-01'::timestamp, NULL, '2004-01-31'::timestamp, 'Consider using M32', now(), now()),
  ('321f466a-542d-4963-8147-1ae30ef0d967', 'MA12', 'You have not established that you have the right under the law to bill for services furnished by the person(s) that furnished this (these) service(s).', true, '1997-01-01'::timestamp, NULL, NULL, NULL, now(), now()),
  ('b9deb7fd-6a83-4bea-9d99-31d7eb85a7c8', 'MA13', 'Alert: You may be subject to penalties if you bill the patient for amounts not reported with the PR (patient responsibility) group code.', true, '1997-01-01'::timestamp, '2007-04-01'::timestamp, NULL, '(Modified 4/1/07)', now(), now()),
  ('9f9549e2-3fe4-46f1-8a9f-6c6dfb721a9e', 'MA14', 'Alert: The patient is a member of an employer-sponsored prepaid health plan. Services from outside that health plan are not covered. However, as you were not previously notified of this, we are paying this time. In the future, we will not pay you for non-plan services.', true, '1997-01-01'::timestamp, '2007-08-01'::timestamp, NULL, '(Modified 4/1/07, 8/1/07)', now(), now()),
  ('f63bbacd-f4f1-4583-a723-e409955da720', 'MA15', 'Alert: Your claim has been separated to expedite handling. You will receive a separate notice for the other services reported.', true, '1997-01-01'::timestamp, '2007-04-01'::timestamp, NULL, '(Modified 4/1/07)', now(), now()),
  ('839d6c23-8317-44a8-93b3-2aabf520743c', 'MA16', 'The patient is covered by the Black Lung Program. Send this claim to the Department of Labor, Federal Black Lung Program, P.O. Box 828, Lanham-Seabrook MD 20703.', true, '1997-01-01'::timestamp, NULL, NULL, NULL, now(), now()),
  ('3588c715-0516-4433-a304-64b74c10c766', 'MA17', 'We are the primary payer and have paid at the primary rate. You must contact the patient''s other insurer to refund any excess it may have paid due to its erroneous primary payment.', true, '1997-01-01'::timestamp, NULL, NULL, NULL, now(), now()),
  ('f5e9269a-54df-419a-9d83-9d55969265b9', 'MA18', 'Alert: The claim information is also being forwarded to the patient''s supplemental insurer. Send any questions regarding supplemental benefits to them.', true, '1997-01-01'::timestamp, '2007-04-01'::timestamp, NULL, '(Modified 4/1/07)', now(), now()),
  ('eac28d1f-05c9-4ea1-9fe1-108c10cd1cb7', 'MA19', 'Alert: Information was not sent to the Medigap insurer due to incorrect/invalid information you submitted concerning that insurer. Please verify your information and submit your secondary claim directly to that insurer.', true, '1997-01-01'::timestamp, '2007-04-01'::timestamp, NULL, '(Modified 4/1/07)', now(), now()),
  ('6358ce82-08af-4cf5-88bc-59385e40aaa7', 'MA20', 'Skilled Nursing Facility (SNF) stay not covered when care is primarily related to the use of an urethral catheter for convenience or the control of incontinence.', true, '1997-01-01'::timestamp, '2003-06-30'::timestamp, NULL, '(Modified 6/30/03)', now(), now()),
