  ('628a09b3-dd57-462f-b7d2-a51ee3338bfc', 'N93', 'A separate claim must be submitted for each place of service. Services furnished at multiple sites may not be billed in the same claim.', true, '2000-01-01'::timestamp, NULL, NULL, NULL, now(), now()),
  ('0008dab6-ed06-4466-bfc3-061520daa013', 'N94', 'Claim/Service denied because a more specific taxonomy code is required for adjudication.', true, '2000-01-01'::timestamp, NULL, NULL, NULL, now(), now()),
  ('23dc8f6e-5dd8-4063-bd42-afe8edb5f7d6', 'N95', 'This provider type/provider specialty may not bill this service.', true, '2001-07-31'::timestamp, '2003-02-28'::timestamp, NULL, '(Modified 2/28/03)', now(), now()),
  ('bdabcd94-b1af-48d3-9f02-e4b328e63d4a', 'N96', 'Patient must be refractory to conventional therapy (documented behavioral, pharmacologic and/or surgical corrective therapy) and be an appropriate surgical candidate such that implantation with anesthesia can occur.', true, '2001-08-24'::timestamp, NULL, NULL, NULL, now(), now()),
  ('d09cd719-d297-4aff-a529-64df55c7b2cf', 'N97', 'Patients with stress incontinence, urinary obstruction, and specific neurologic diseases (e.g., diabetes with peripheral nerve involvement) which are associated with secondary manifestations of the above three indications are excluded.', true, '2001-08-24'::timestamp, NULL, NULL, NULL, now(), now()),
  ('7eca732f-f6c2-4f44-ae4c-6e6ad50da393', 'N98', 'Patient must have had a successful test stimulation in order to support subsequent implantation. Before a patient is eligible for permanent implantation, he/she must demonstrate a 50 percent or greater improvement through test stimulation. Improvement is measured through voiding diaries.', true, '2001-08-24'::timestamp, NULL, NULL, NULL, now(), now()),
  ('e35a1fd1-663d-48a8-84d8-a9d34d715245', 'N99', 'Patient must be able to demonstrate adequate ability to record voiding diary data such that clinical results of the implant procedure can be properly evaluated.', true, '2001-08-24'::timestamp, NULL, NULL, NULL, now(), now()),
  ('40209adb-f631-4d0d-9be0-7f449d4f40d6', 'N100', 'PPS (Prospect Payment System) code corrected during adjudication.', false, '2001-09-14'::timestamp, '2015-11-01'::timestamp, '2016-11-01'::timestamp, '(Modified 6/30/03, 11/1/2015)', now(), now()),
  ('22ea17d1-a915-4869-a934-653159f69851', 'N101', 'Additional information is needed in order to process this claim. Please resubmit the claim with the identification number of the provider where this service took place. The Medicare number of the site of service provider should be preceded with the letters ''HSP'' and entered into item #32 on the claim form. You may bill only one site of service provider number per claim.', false, '2001-10-31'::timestamp, '2014-03-14'::timestamp, '2004-01-31'::timestamp, 'Consider using MA105 (Modified 3/14/2014)', now(), now()),
  ('beeff336-14df-4643-b520-93307f5707ff', 'N102', 'This claim has been denied without reviewing the medical/dental record because the requested records were not received or were not received timely.', false, '2001-10-31'::timestamp, '2013-11-01'::timestamp, '2016-07-01'::timestamp, NULL, now(), now()),
  ('a95a166d-0fa2-4d7a-8aec-11a738723a37', 'N103', 'Records indicate this patient was a prisoner or in custody of a Federal, State, or local authority when the service was rendered. This payer does not cover items and services furnished to an individual while he or she is in custody under a penal statute or rule, unless under State or local law, the individual is personally liable for the cost of his or her health care while in custody and the State or local government pursues the collection of such debt in the same way and with the same vigor as the collection of its other debts. The provider can collect from the Federal/State/ Local Authority as appropriate.', true, '2001-10-31'::timestamp, '2013-11-01'::timestamp, NULL, '(Modified 6/30/03, 7/1/12, 11/1/13)', now(), now()),
  ('aa9eedb2-bc70-491b-a2ac-e112ad8a84ef', 'N104', 'This claim/service is not payable under our claims jurisdiction area. You can identify the correct Medicare contractor to process this claim/service through the CMS website at www.cms.gov.', true, '2002-01-29'::timestamp, '2010-07-01'::timestamp, NULL, '(Modified 10/31/02, 7/1/10)', now(), now()),
  ('37748a51-5b92-4a5a-9f5b-6fc146e22277', 'N105', 'This is a misdirected claim/service for an RRB beneficiary. Submit paper claims to the RRB carrier: Palmetto GBA, P.O. Box 10066, Augusta, GA 30999. Call 888-355-9165 for RRB EDI information for electronic claims processing.', true, '2002-01-29'::timestamp, '2017-07-01'::timestamp, NULL, '(Modified 7/1/2017)', now(), now()),
  ('30c3892b-30cd-4e76-886d-f55b9e09fb01', 'N106', 'Payment for services furnished to Skilled Nursing Facility (SNF) inpatients (except for excluded services) can only be made to the SNF. You must request payment from the SNF rather than the patient for this service.', true, '2002-01-31'::timestamp, NULL, NULL, NULL, now(), now()),
  ('894c10a1-304c-4362-b4c7-a585ab9f7922', 'N107', 'Services furnished to Skilled Nursing Facility (SNF) inpatients must be billed on the inpatient claim. They cannot be billed separately as outpatient services.', true, '2002-01-31'::timestamp, NULL, NULL, NULL, now(), now()),
  ('090566e7-23d4-4c22-88f1-ad339d5fad4a', 'N108', 'Missing/incomplete/invalid upgrade information.', true, '2002-01-31'::timestamp, '2003-02-28'::timestamp, NULL, '(Modified 2/28/03)', now(), now()),
