  ('41e735db-3c63-44f7-884d-bd045205d4f7', 'N112', 'This claim is excluded from your electronic remittance advice.', true, '2002-02-28'::timestamp, NULL, NULL, NULL, now(), now()),
  ('3d9e3ed8-9126-43c1-9b89-d331fe0eaa75', 'N113', 'Only one initial visit is covered per physician, group practice or provider.', true, '2002-04-16'::timestamp, '2003-06-30'::timestamp, NULL, '(Modified 6/30/03)', now(), now()),
  ('c36c5c24-bfc6-42e2-8536-2840a91d8f0d', 'N114', 'During the transition to the Ambulance Fee Schedule, payment is based on the lesser of a blended amount calculated using a percentage of the reasonable charge/cost and fee schedule amounts, or the submitted charge for the service. You will be notified yearly what the percentages for the blended payment calculation will be.', true, '2002-05-30'::timestamp, NULL, NULL, NULL, now(), now()),
  ('481319bf-e88e-4958-bbe9-67f355eaf284', 'N115', 'This decision was based on a Local Coverage Determination (LCD). An LCD provides a guide to assist in determining whether a particular item or service is covered. A copy of this policy is available at www.cms.gov/mcd, or if you do not have web access, you may contact the contractor to request a copy of the LCD.', true, '2002-05-30'::timestamp, '2010-07-01'::timestamp, NULL, '(Modified 4/1/04, 7/1/10)', now(), now()),
  ('c79f8e29-f7cc-4ee3-8c25-3e2cff16b469', 'N116', 'Alert: This payment is being made conditionally because the service was provided in the home, and it is possible that the patient is under a home health episode of care. When a patient is treated under a home health episode of care, consolidated billing requires that certain therapy services and supplies, such as this, be included in the home health agency''s (HHA''s) payment. This payment will need to be recouped from you if we establish that the patient is concurrently receiving treatment under an HHA episode of care.', true, '2002-06-30'::timestamp, '2016-11-01'::timestamp, NULL, '(Modified 11/1/2016)', now(), now()),
  ('44424a2f-0ce0-480a-b69c-ff86dbf160bd', 'N117', 'This service is paid only once in a patient''s lifetime.', true, '2002-07-30'::timestamp, '2003-06-30'::timestamp, NULL, '(Modified 6/30/03)', now(), now()),
  ('31a99215-0061-4d51-9f7d-31951bec4410', 'N118', 'This service is not paid if billed more than once every 28 days.', true, '2002-07-30'::timestamp, NULL, NULL, NULL, now(), now()),
  ('d589bd42-c3be-4027-aa5e-47e337a0c720', 'N119', 'This service is not paid if billed once every 28 days, and the patient has spent 5 or more consecutive days in any inpatient or Skilled /nursing Facility (SNF) within those 28 days.', true, '2002-07-30'::timestamp, '2003-06-30'::timestamp, NULL, '(Modified 6/30/03)', now(), now()),
  ('49cb9db7-20ff-416b-aa05-986993e4b0a1', 'N120', 'Payment is subject to home health prospective payment system partial episode payment adjustment. Patient was transferred/discharged/readmitted during payment episode.', true, '2002-08-09'::timestamp, '2003-06-30'::timestamp, NULL, '(Modified 6/30/03)', now(), now()),
  ('d15ecc2f-2aa3-48c5-a60a-0a278118b988', 'N121', 'Medicare Part B does not pay for items or services provided by this type of practitioner for beneficiaries in a Medicare Part A covered Skilled Nursing Facility (SNF) stay.', true, '2002-09-09'::timestamp, '2004-08-01'::timestamp, NULL, '(Modified 8/1/04, 6/30/03)', now(), now()),
  ('7275f6c8-5bc9-4c60-a0c4-f9f3bf5b1cea', 'N122', 'Add-on code cannot be billed by itself.', true, '2002-09-12'::timestamp, '2005-08-01'::timestamp, NULL, '(Modified 8/1/05)', now(), now()),
  ('2be5d0c5-5afd-400f-9ff0-4507643a833f', 'N123', 'Alert: This is a split service and represents a portion of the units from the originally submitted service.', true, '2002-09-24'::timestamp, '2016-03-01'::timestamp, NULL, '(Modified 3/1/2016)', now(), now()),
  ('ada9d5e0-03f3-4a99-b2b6-c46a021a4634', 'N124', 'Payment has been denied for the/made only for a less extensive service/item because the information furnished does not substantiate the need for the (more extensive) service/item. The patient is liable for the charges for this service/item as you informed the patient in writing before the service/item was furnished that we would not pay for it, and the patient agreed to pay.', true, '2002-09-26'::timestamp, NULL, NULL, NULL, now(), now()),
  ('517ea027-6c01-404e-a344-ced888d801a1', 'N125', 'Payment has been (denied for the/made only for a less extensive) service/item because the information furnished does not substantiate the need for the (more extensive) service/item. If you have collected any amount from the patient, you must refund that amount to the patient within 30 days of receiving this notice.The requirements for a refund are in §1834(a)(18) of the Social Security Act (and in §§1834(j)(4) and 1879(h) by cross-reference to §1834(a)(18)). Section 1834(a)(18)(B) specifies that suppliers which knowingly and willfully fail to make appropriate refunds may be subject to civil money penalties and/or exclusion from the Medicare program. If you have any questions about this notice, please contact this office.', true, '2002-09-26'::timestamp, '2005-08-01'::timestamp, NULL, '(Modified 8/1/05. Also refer to N356)', now(), now()),
  ('ec945ace-1b30-4804-8079-654d19a0508a', 'N126', 'Social Security Records indicate that this individual has been deported. This payer does not cover items and services furnished to individuals who have been deported.', true, '2002-10-17'::timestamp, NULL, NULL, NULL, now(), now()),
  ('8df6ec79-5859-408a-8073-9a9397ca8c02', 'N127', 'This is a misdirected claim/service for a United Mine Workers of America (UMWA) beneficiary. Please submit claims to them.', true, '2007-10-31'::timestamp, '2004-08-01'::timestamp, NULL, '(Modified 8/1/04', now(), now()),
  ('22513d29-72a5-4354-9ee9-2c8054cb4c66', 'N128', 'This amount represents the prior to coverage portion of the allowance.', true, '2002-10-31'::timestamp, NULL, NULL, NULL, now(), now()),
