-- Full official CARC (Claim Adjustment Reason Codes) and RARC (Remittance
-- Advice Remark Codes) reference data, sourced from X12.org's published code
-- lists (https://x12.org/codes/claim-adjustment-reason-codes and
-- https://x12.org/codes/remittance-advice-remark-codes) as of 2026-08-19.
-- Includes both active and deactivated codes (deactivated ones carry a stopDate
-- and often a "Notes" pointer to the replacement code, per the source page).
--
-- X12 revises these lists three times a year (March/July/November) -- re-running
-- this style of upsert against a fresh pull is the way to refresh it later.
ON CONFLICT (code) DO UPDATE SET
  description  = EXCLUDED.description,
  active       = EXCLUDED.active,
  "startDate"  = EXCLUDED."startDate",
  "lastModified" = EXCLUDED."lastModified",
  "stopDate"   = EXCLUDED."stopDate",
  notes        = EXCLUDED.notes,
  "updatedAt"  = now();
